-- Verified wallet links (issue #78): generalize WalletLink from
-- facility-only/typed-in to an owner (patient | facility) with a
-- verification method, and snapshot the funded payee address on
-- PaymentIntent.
--
-- Hand-ordered (generated by `prisma migrate diff`, then rewritten):
-- the generated script added NOT NULL columns and dropped `facilityId`
-- before any backfill, which fails on a populated table. This version
-- adds columns nullable → backfills from `facilityId` → constrains →
-- only then drops the old shape, so it is safe to run against existing
-- data (every pre-existing facility row becomes an active
-- `unverified_legacy` link owned by its facility).
--
-- Reversibility: reversing back to the old shape is practical only for
-- `ownerType = 'facility'` rows (recreate `facilityId` from `ownerId`,
-- restore the FK/unique index); patient-era rows and verified metadata
-- have no old-shape home, so a down migration would drop them. Not
-- written for that reason — restore from backup if reversal is needed.

-- CreateEnum
CREATE TYPE "WalletLinkOwnerType" AS ENUM ('patient', 'facility');

-- CreateEnum
CREATE TYPE "WalletLinkVerificationMethod" AS ENUM ('sep10', 'unverified_legacy');

-- AlterTable: PaymentIntent gains the funding-time payee snapshot (null
-- until the next funding; no backfill possible — historical intents
-- never recorded their payee address).
ALTER TABLE "PaymentIntent" ADD COLUMN "fundedWalletAddress" TEXT;

-- AlterTable: new columns nullable first so rows can be backfilled.
ALTER TABLE "WalletLink" ADD COLUMN "activeOwnerKey" TEXT;
ALTER TABLE "WalletLink" ADD COLUMN "ownerId" TEXT;
ALTER TABLE "WalletLink" ADD COLUMN "ownerType" "WalletLinkOwnerType";
ALTER TABLE "WalletLink" ADD COLUMN "replacedAt" TIMESTAMP(3);
ALTER TABLE "WalletLink" ADD COLUMN "verificationMethod" "WalletLinkVerificationMethod";
ALTER TABLE "WalletLink" ADD COLUMN "verifiedAt" TIMESTAMP(3);

-- Backfill: every existing row was a facility link typed in by hand →
-- active, owned by its facility, explicitly marked unverified. Their
-- addresses were never SEP-10-checked, so `verifiedAt` stays NULL and
-- funding honours them only until WALLET_LINK_UNVERIFIED_FUNDING_CUTOFF.
UPDATE "WalletLink"
SET "ownerType" = 'facility',
    "ownerId" = "facilityId",
    "verificationMethod" = 'unverified_legacy',
    "activeOwnerKey" = 'facility:' || "facilityId"
WHERE "facilityId" IS NOT NULL;

-- Now constrain (all rows backfilled above; table empty if fresh).
ALTER TABLE "WalletLink" ALTER COLUMN "ownerType" SET NOT NULL;
ALTER TABLE "WalletLink" ALTER COLUMN "ownerId" SET NOT NULL;
ALTER TABLE "WalletLink" ALTER COLUMN "verificationMethod" SET NOT NULL;

-- Drop old facility-only shape (FK must go before the column).
ALTER TABLE "WalletLink" DROP CONSTRAINT "WalletLink_facilityId_fkey";
DROP INDEX "WalletLink_facilityId_key";
ALTER TABLE "WalletLink" DROP COLUMN "facilityId";

-- CreateIndex
-- The one-active-link-per-owner DB guarantee: unique on the sentinel
-- column that is non-NULL exactly while the link is active.
CREATE UNIQUE INDEX "WalletLink_activeOwnerKey_key" ON "WalletLink"("activeOwnerKey");

-- CreateIndex
CREATE INDEX "WalletLink_ownerType_ownerId_idx" ON "WalletLink"("ownerType", "ownerId");
